import { announce, definePrimitive } from "@ui-sdk/core"

import { unavailable } from "@/lib/action-refusal"

type DeviceDecision = "approve" | "deny"

type DeviceApprovalOptions = {
  /** Approves the device; a returned Promise keeps the block pending, and a rejection shows the error. */
  onApprove?: () => unknown
  /** Denies the device, with the same pending and error handling. */
  onDeny?: () => unknown
  /** Runs once, when the request expires. */
  onExpire?: () => void
  /** Why approving waits, like codes that don't match yet; `null` when nothing stops it. */
  approveBlocked?: string | null
  expiredAnnouncement?: string
}

type DeviceApprovalState = {
  /** The decision being sent. */
  pending: DeviceDecision | null
  /** The decision the app accepted. */
  decided: DeviceDecision | null
  error: unknown
  expired: boolean
}

const isThenable = (value: unknown): value is PromiseLike<unknown> =>
  typeof value === "object" && value !== null && "then" in value && typeof value.then === "function"

const pastTense: Record<DeviceDecision, string> = { approve: "approved", deny: "denied" }

const deviceApproval = definePrimitive({
  name: "device-approval",
  options: {
    onApprove: "callback",
    onDeny: "callback",
    onExpire: "callback",
    approveBlocked: "value",
    expiredAnnouncement: "string",
  },
  controlled: ["pending", "decided", "expired"],
  state: (_options: DeviceApprovalOptions): DeviceApprovalState => ({
    pending: null,
    decided: null,
    error: null,
    expired: false,
  }),
  api: (context) => {
    let destroyed = false
    context.onDestroy(() => {
      destroyed = true
    })

    const decide = (decision: DeviceDecision, event: Event | undefined): Promise<DeviceDecision> | boolean => {
      const call = { event }
      const { pending, decided, expired } = context.store.get()
      if (decided !== null) {
        return unavailable(decision, `isn't available: the device was already ${pastTense[decided]}`, call)
      }
      if (pending !== null) return unavailable(decision, "isn't available while a decision is being sent", call)
      if (expired) return unavailable(decision, "isn't available: the request has expired", call)
      const options = context.options()
      const blocked = decision === "approve" ? options.approveBlocked : null
      if (blocked) return unavailable(decision, `isn't available: ${blocked}`, call)
      const run = decision === "approve" ? options.onApprove : options.onDeny
      if (!run)
        return unavailable(
          decision,
          `isn't available: the block has no on${decision === "approve" ? "Approve" : "Deny"}`,
          call,
        )
      context.store.set({ pending: decision, error: null })
      let result: unknown
      try {
        result = run()
      } catch (error) {
        context.store.set({ pending: null, error })
        return Promise.reject(error instanceof Error ? error : new Error(String(error)))
      }
      if (!isThenable(result)) {
        context.store.set({ pending: null, decided: decision })
        return true
      }
      return Promise.resolve(result).then(
        () => {
          if (!destroyed) context.store.set({ pending: null, decided: decision })
          return decision
        },
        (error: unknown) => {
          if (!destroyed) context.store.set({ pending: null, error })
          throw error
        },
      )
    }

    return {
      /** Approves the device through `onApprove`. The Approve button asks an agent's person first. */
      approve(event?: Event) {
        return decide("approve", event)
      },
      /** Denies the device through `onDeny`. */
      deny(event?: Event) {
        return decide("deny", event)
      },
      /** Marks the request expired, once: approving stops, `onExpire` runs and the expiry is announced. */
      expire() {
        if (context.store.get().expired) return
        context.store.set({ expired: true })
        const { onExpire, expiredAnnouncement } = context.options()
        if (expiredAnnouncement) announce(expiredAnnouncement)
        onExpire?.()
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, DeviceApprovalState>({
      state: (state) => ({ ...state }),
      attrs: (state) => ({
        role: "group",
        "aria-busy": state.pending === null ? undefined : "true",
        "data-pending": state.pending ?? undefined,
        "data-decided": state.decided ?? undefined,
        "data-expired": state.expired ? "" : undefined,
      }),
    }),
  }),
  agent: { actions: ["deny"] },
})

type DeviceApprovalApproveOptions = {
  /** The block's `approve`, which decides whether it runs. */
  approve?: (event?: Event) => unknown
  /** Disables the person's button; an agent's step still reaches `approve`, which says why it refuses. */
  blocked?: boolean
  pending?: boolean
}

type DeviceApprovalApproveState = { blocked: boolean; pending: boolean }

const deviceApprovalApprove = definePrimitive({
  name: "device-approval-approve",
  options: { approve: "callback", blocked: "boolean", pending: "boolean" },
  state: (options: DeviceApprovalApproveOptions): DeviceApprovalApproveState => ({
    blocked: options.blocked ?? false,
    pending: options.pending ?? false,
  }),
  sync: (options) => ({ blocked: options.blocked ?? false, pending: options.pending ?? false }),
  api: (context) => ({
    /** Approves the device; an agent's step needs a person, through the button's `data-agent-confirm`. */
    approve(event?: Event) {
      const { approve } = context.options()
      if (!approve) return unavailable("approve", "isn't available: the block renders its own actions", { event })
      return approve(event)
    },
  }),
  slots: (slot) => ({
    root: slot<{}, DeviceApprovalApproveState>({
      state: (state) => ({ ...state }),
      attrs: (state) => ({
        role: "group",
        "data-blocked": state.blocked ? "" : undefined,
        "data-pending": state.pending ? "" : undefined,
      }),
    }),
  }),
  agent: { actions: ["approve"] },
})

export { deviceApproval, deviceApprovalApprove }
export type {
  DeviceApprovalApproveOptions,
  DeviceApprovalApproveState,
  DeviceApprovalOptions,
  DeviceApprovalState,
  DeviceDecision,
}

"use client"

import { announce } from "@ui-sdk/core"
import { useCallback, useEffect, useEffectEvent, useRef, useSyncExternalStore } from "react"

const LONGEST_TIMEOUT_MS = 2 ** 31 - 1
const SECOND_MS = 1000
const FINAL_STRETCH_S = 30
const FINAL_STEP_S = 10

const secondsLeft = (expiresAt: number) => Math.max(0, Math.ceil((expiresAt - Date.now()) / SECOND_MS))

function subscribeUntil(expiresAt: number, nextDelay: (leftMs: number) => number) {
  return (notify: () => void) => {
    let timer: ReturnType<typeof setTimeout> | undefined
    const arm = () => {
      clearTimeout(timer)
      timer = undefined
      notify()
      if (document.hidden) return
      const left = expiresAt - Date.now()
      if (left <= 0) return
      timer = setTimeout(arm, Math.min(nextDelay(left), LONGEST_TIMEOUT_MS))
    }
    arm()
    document.addEventListener("visibilitychange", arm)
    return () => {
      clearTimeout(timer)
      document.removeEventListener("visibilitychange", arm)
    }
  }
}

/**
 * Whether `expiresAt` (epoch ms) has passed, with one timeout and none while the page is hidden; coming back checks
 * the clock. Runs `onExpire` once it passes, or on mount when it already has.
 */
function useDeviceApprovalExpiry(expiresAt: number | undefined, onExpire: () => void) {
  const subscribe = useCallback(
    (notify: () => void) =>
      expiresAt === undefined ? () => undefined : subscribeUntil(expiresAt, (left) => left)(notify),
    [expiresAt],
  )
  const expired = useSyncExternalStore(
    subscribe,
    () => expiresAt !== undefined && expiresAt <= Date.now(),
    () => false,
  )
  const expire = useEffectEvent(onExpire)

  useEffect(() => {
    if (expired) expire()
  }, [expired])

  return expired
}

/** The whole seconds left until `expiresAt`, updated on each second's boundary while the page is visible. */
function useSecondsLeft(expiresAt: number) {
  const subscribe = useCallback(
    (notify: () => void) => subscribeUntil(expiresAt, (left) => left % SECOND_MS || SECOND_MS)(notify),
    [expiresAt],
  )
  return useSyncExternalStore(
    subscribe,
    () => secondsLeft(expiresAt),
    () => secondsLeft(expiresAt),
  )
}

/** Once a minute, then every ten seconds in the last thirty; `null` once it's over. */
function announcementStep(seconds: number) {
  if (seconds <= 0) return null
  if (seconds > FINAL_STRETCH_S) return Math.ceil(seconds / 60) * 60
  return Math.ceil(seconds / FINAL_STEP_S) * FINAL_STEP_S
}

/**
 * Announces the time left politely when it reaches a whole minute, and every ten seconds in the last thirty; never
 * on the first render, so a page that opens doesn't talk over itself.
 */
function useCountdownAnnouncements(seconds: number, message: ((seconds: number) => string) | undefined) {
  const step = announcementStep(seconds)
  const announced = useRef<number | null | undefined>(undefined)
  const say = useEffectEvent((at: number) => {
    if (message) announce(message(at))
  })

  useEffect(() => {
    const previous = announced.current
    announced.current = step
    if (previous === undefined || step === null || step === previous) return
    say(step)
  }, [step])
}

export { announcementStep, useCountdownAnnouncements, useDeviceApprovalExpiry, useSecondsLeft }

"use client"

import { usePart, usePrimitive } from "@ui-sdk/react/primitive"
import { BanIcon, CheckIcon } from "lucide-react"
import { useId, type ReactNode } from "react"

import { Button } from "@/components/ui/button"
import { deviceApprovalApprove } from "@/components/ui/device-approval-primitive"
import { useCountdownAnnouncements, useSecondsLeft } from "@/components/ui/use-device-approval-expiry"
import { cn } from "@/lib/utils"

type DevicePermission = {
  id: string
  label: ReactNode
  description?: ReactNode
  /** Why it's withheld, like "Your role can't grant this". */
  reason?: ReactNode
}

const approveAttributes = (agentConfirm: string): Record<`data-${string}`, string> => ({
  "data-slot": "device-approval-approve",
  "data-agent-confirm": agentConfirm,
})

const ignoreRefusal = () => undefined

function formatRemaining(seconds: number) {
  const hours = Math.floor(seconds / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)
  const rest = String(seconds % 60).padStart(2, "0")
  return hours > 0 ? `${String(hours)}:${String(minutes).padStart(2, "0")}:${rest}` : `${String(minutes)}:${rest}`
}

function hasContent(node: ReactNode) {
  return node !== undefined && node !== null && node !== false
}

const permissionLook = {
  granted: {
    icon: <CheckIcon strokeWidth={2.5} />,
    className: "border-success-border bg-success-soft text-success-soft-foreground",
  },
  withheld: {
    icon: <BanIcon strokeWidth={2.5} />,
    className: "border-warning-border bg-warning-soft text-warning-soft-foreground",
  },
}

function PermissionSection({
  kind,
  heading,
  permissions,
}: {
  kind: "granted" | "withheld"
  heading: ReactNode
  permissions: readonly DevicePermission[]
}) {
  const headingId = useId()
  if (permissions.length === 0) return null
  const look = permissionLook[kind]
  return (
    <section
      data-slot={`device-approval-${kind}`}
      aria-labelledby={headingId}
      className="flex min-w-0 flex-col gap-items"
    >
      <h3 id={headingId} className="text-title-sm">
        {heading}
      </h3>
      <ul aria-labelledby={headingId} className="flex flex-col gap-items">
        {permissions.map((permission) => (
          <li key={permission.id} data-slot="device-approval-permission" className="flex items-start gap-items">
            <span
              aria-hidden="true"
              className={cn(
                "flex size-6 shrink-0 items-center justify-center rounded-full border [&_svg]:size-3.5",
                look.className,
              )}
            >
              {look.icon}
            </span>
            <span className="flex min-w-0 flex-col">
              <span className="text-body font-medium">{permission.label}</span>
              {hasContent(permission.description) ? (
                <span className="text-body-sm text-muted-foreground">{permission.description}</span>
              ) : null}
              {hasContent(permission.reason) ? (
                <span data-slot="device-approval-reason" className="text-caption text-muted-foreground">
                  {permission.reason}
                </span>
              ) : null}
            </span>
          </li>
        ))}
      </ul>
    </section>
  )
}

function Countdown({
  expiresAt,
  expiresIn,
}: {
  expiresAt: number
  expiresIn: (remainingMs: number, formatted: string) => string
}) {
  const seconds = useSecondsLeft(expiresAt)
  useCountdownAnnouncements(seconds, (at) => expiresIn(at * 1000, formatRemaining(at)))
  return (
    <p
      role="timer"
      data-slot="device-approval-countdown"
      className="flex items-center gap-inline text-body-sm text-muted-foreground tabular-nums"
    >
      {expiresIn(seconds * 1000, formatRemaining(seconds))}
    </p>
  )
}

function ApproveButton({
  approve,
  blocked,
  pending,
  describedBy,
  agentConfirm,
  children,
}: {
  approve: (event?: Event) => unknown
  blocked: boolean
  pending: boolean
  describedBy?: string
  agentConfirm: string
  children: ReactNode
}) {
  const handle = usePrimitive(deviceApprovalApprove, { approve, blocked, pending })
  const buttonId = useId()
  return usePart(
    handle,
    "root",
    {},
    {
      ...approveAttributes(agentConfirm),
      "aria-labelledby": buttonId,
      className: "contents",
      children: (
        <Button
          id={buttonId}
          aria-describedby={describedBy}
          data-agent-hidden=""
          className="narrow:w-full"
          disabled={blocked}
          focusableWhenDisabled
          loading={pending}
          onClick={(event) => {
            const result = handle.api.approve(event.nativeEvent)
            if (result instanceof Promise) result.then(undefined, ignoreRefusal)
          }}
        >
          <CheckIcon />
          {children}
        </Button>
      ),
    },
    "span",
  )
}

export { ApproveButton, Countdown, PermissionSection }
export type { DevicePermission }

"use client"

import { usePart, usePrimitive } from "@ui-sdk/react/primitive"
import { CircleSlashIcon, ClockAlertIcon, MonitorSmartphoneIcon, TriangleAlertIcon } from "lucide-react"
import { useId, useState, type ReactNode } from "react"

import { Alert, AlertDescription } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  ApproveButton,
  Countdown,
  PermissionSection,
  type DevicePermission,
} from "@/components/ui/device-approval-parts"
import {
  deviceApproval,
  type DeviceApprovalState,
  type DeviceDecision,
} from "@/components/ui/device-approval-primitive"
import {
  PairingCode,
  type PairingCodeConfirmText,
  type PairingCodeEnterText,
  type PairingCodeLabels,
} from "@/components/ui/pairing-code"
import { useDeviceApprovalExpiry } from "@/components/ui/use-device-approval-expiry"
import { rejectionContent, type RejectionFallback } from "@/lib/rejection-content"
import { cn } from "@/lib/utils"

/** The device asking for access. */
type DeviceInfo = {
  name: string
  /** Free text, like "Desktop" or "Node". */
  kind?: string
  /** Replaces the default device icon. */
  icon?: ReactNode
  /** A line under the name, like where and when it asked. */
  detail?: ReactNode
}

/** The block's visible text. None has a default: pass it in the page's language. */
type DeviceApprovalText = {
  /** Under the device, like "This device asked to connect to your account." */
  description?: ReactNode
  /** Names the pairing code, when `code` is given; "Pairing code" by default. */
  code?: string
  /** The heading over what the device gets. */
  granted: ReactNode
  /** The heading over what it asked for and won't get. */
  withheld: ReactNode
  approve: ReactNode
  deny: ReactNode
  /** What a person approves when an agent approves, like "Gives Studio laptop access to your account". */
  approveAgentConfirm: string
  /**
   * Shown in a live alert when approving or denying fails with something other than a string or a node, which show as
   * they are; a function of the error picks one per failure.
   */
  error: RejectionFallback
  /** The time left, from the milliseconds left and the same as `m:ss`; shown each second and read once a minute. */
  expiresIn?: (remainingMs: number, formatted: string) => string
  /** Shown, and read, once `expiresAt` passes. */
  expired?: string
  /** Shown, and read, once the app accepts the approval. */
  approved?: ReactNode
  denied?: ReactNode
}

/** Names for screen readers and agents; English by default. `codeLabels` holds the inner PairingCode's. */
type DeviceApprovalLabels = {
  /** Names the pairing code; `text.code` wins over it. */
  code: string
}

const deviceApprovalLabels: DeviceApprovalLabels = { code: "Pairing code" }

/** What a consumer's own `actions` can render from. */
type DeviceApprovalActionState = {
  expired: boolean
  /** Whether the codes match, with `code` and `compare`; `null` without a comparison or before an answer. */
  codesMatch: boolean | null
  /** True while the app (`approveBlocked`), the comparison or the expiry stops an approval. */
  approveBlocked: boolean
}

type DeviceApprovalBaseProps = {
  device: DeviceInfo
  /** The pairing code shown on the other screen, rendered with PairingCode. */
  code?: string
  groupSize?: number
  separator?: string
  /** Keeps the code and its comparison from agents; on by default, so an agent never reads or types the code. */
  agentHidden?: boolean
  granted?: readonly DevicePermission[]
  withheld?: readonly DevicePermission[]
  /** A security warning, shown in a warning Alert. */
  warning?: ReactNode
  /** When the request expires; approving stops then. */
  expiresAt?: Date | number
  /** Runs once, when `expiresAt` passes. */
  onExpire?: () => void
  /** Turns Approve off for a reason of the app's, like an account that can't grant any requested permission. */
  approveBlocked?: boolean
  /**
   * Why `approveBlocked` stops approving, in the page's language: shown beside the actions, describing Approve, and the
   * message an agent's `approve` fails with. Without it, nothing shows and an agent reads an English reason.
   */
  approveBlockedReason?: string
  text: DeviceApprovalText
  labels?: Partial<DeviceApprovalLabels>
  /** The inner PairingCode's names (its copy button and the spelled-out code), merged over its English defaults. */
  codeLabels?: Partial<PairingCodeLabels>
  className?: string
}

type DeviceApprovalCompareProps =
  | { compare?: undefined; compareText?: undefined }
  | { compare: "confirm"; compareText: PairingCodeConfirmText; onConfirm?: (matches: boolean) => unknown }
  | { compare: "enter"; compareText: PairingCodeEnterText; onMatchChange?: (matches: boolean) => void }

type DeviceApprovalActionProps =
  | {
      /**
       * Approves the device; a returned Promise keeps the block pending, and a rejection shows in the error alert: a
       * string or a node as it is, anything else through `text.error`.
       */
      onApprove: () => unknown
      onDeny: () => unknown
      actions?: undefined
    }
  | {
      /** Your own actions in place of Approve and Deny. Mark an approve control with `data-agent-confirm`. */
      actions: ReactNode | ((state: DeviceApprovalActionState) => ReactNode)
      onApprove?: undefined
      onDeny?: undefined
    }

type DeviceApprovalProps = DeviceApprovalBaseProps & DeviceApprovalCompareProps & DeviceApprovalActionProps

const rootAttributes: Record<`data-${string}`, string> = { "data-slot": "device-approval" }

const noPermissions: readonly DevicePermission[] = []

const ignoreRefusal = () => undefined

function hasContent(node: ReactNode) {
  return node !== undefined && node !== null && node !== false
}

const appBlockedFallback = "the app doesn't allow approving this request"

function compareBlockedReason(compare: DeviceApprovalProps["compare"], codesMatch: boolean | null) {
  if (compare === "confirm" && codesMatch !== true) return "the person hasn't confirmed that the codes match"
  if (compare === "enter" && codesMatch !== true) return "the typed code doesn't match the device's code"
  return null
}

function DeviceApproval(props: DeviceApprovalProps) {
  const {
    device,
    code,
    groupSize,
    separator,
    agentHidden = true,
    granted = noPermissions,
    withheld = noPermissions,
    warning,
    expiresAt,
    onExpire,
    approveBlocked = false,
    approveBlockedReason,
    text,
    labels: overrides,
    codeLabels,
    className,
  } = props
  const labels = { ...deviceApprovalLabels, ...overrides }
  const nameId = useId()
  const blockedReasonId = useId()
  const [codesMatch, setCodesMatch] = useState<boolean | null>(null)
  const comparing = code !== undefined && props.compare !== undefined
  const compareBlocked = comparing ? compareBlockedReason(props.compare, codesMatch) : null
  const blocked = approveBlocked ? (approveBlockedReason ?? appBlockedFallback) : compareBlocked
  const handle = usePrimitive(deviceApproval, {
    onApprove: props.onApprove,
    onDeny: props.onDeny,
    onExpire,
    approveBlocked: blocked,
    expiredAnnouncement: text.expired,
  })
  const { api } = handle
  const expiry = expiresAt instanceof Date ? expiresAt.getTime() : expiresAt
  useDeviceApprovalExpiry(expiry, () => api.expire())

  const pairing = (() => {
    if (code === undefined) return null
    const shared = { code, label: text.code ?? labels.code, groupSize, separator, agentHidden, labels: codeLabels }
    if (props.compare === "confirm") {
      return (
        <PairingCode
          {...shared}
          compare="confirm"
          text={props.compareText}
          onConfirm={(matches) => {
            setCodesMatch(matches)
            return props.onConfirm?.(matches)
          }}
        />
      )
    }
    if (props.compare === "enter") {
      return (
        <PairingCode
          {...shared}
          compare="enter"
          text={props.compareText}
          onMatchChange={(matches) => {
            setCodesMatch(matches)
            props.onMatchChange?.(matches)
          }}
        />
      )
    }
    return <PairingCode {...shared} />
  })()

  const decidedText = (decided: DeviceDecision | null) => {
    if (decided === "approve") return text.approved
    if (decided === "deny") return text.denied
    return undefined
  }

  return usePart(
    handle,
    "root",
    {},
    {
      ...rootAttributes,
      "aria-labelledby": nameId,
      className: cn("@container flex min-w-0 flex-col gap-group", className),
      children: (state: DeviceApprovalState) => {
        const decision = decidedText(state.decided)
        const undecided = !state.expired && state.decided === null
        const showBlockedReason = approveBlocked && undecided && approveBlockedReason !== undefined
        const actionState: DeviceApprovalActionState = {
          expired: state.expired,
          codesMatch: comparing ? codesMatch : null,
          approveBlocked: state.expired || blocked !== null,
        }
        return (
          <>
            <div data-slot="device-approval-device" className="flex min-w-0 items-start gap-items">
              <span
                aria-hidden="true"
                className="flex size-control shrink-0 items-center justify-center rounded-control border bg-muted text-muted-foreground [&_svg]:size-5"
              >
                {device.icon ?? <MonitorSmartphoneIcon />}
              </span>
              <div className="flex min-w-0 flex-col gap-inline">
                <div className="flex min-w-0 flex-wrap items-center gap-inline">
                  <h2 id={nameId} className="min-w-0 text-title-sm break-words">
                    {device.name}
                  </h2>
                  {device.kind === undefined ? null : <Badge variant="secondary">{device.kind}</Badge>}
                </div>
                {hasContent(device.detail) ? (
                  <div className="text-body-sm text-muted-foreground">{device.detail}</div>
                ) : null}
              </div>
            </div>
            {hasContent(text.description) ? (
              <p className="text-body text-muted-foreground">{text.description}</p>
            ) : null}
            {pairing}
            {hasContent(warning) ? (
              <Alert data-slot="device-approval-warning" tone="warning">
                <TriangleAlertIcon />
                <AlertDescription>{warning}</AlertDescription>
              </Alert>
            ) : null}
            {granted.length > 0 || withheld.length > 0 ? (
              <div className="grid min-w-0 gap-group @xl:grid-cols-2">
                <PermissionSection kind="granted" heading={text.granted} permissions={granted} />
                <PermissionSection kind="withheld" heading={text.withheld} permissions={withheld} />
              </div>
            ) : null}
            {state.expired ? (
              <p
                data-slot="device-approval-expired"
                className="flex items-center gap-inline text-body-sm font-medium text-warning-soft-foreground [&_svg]:size-4"
              >
                <ClockAlertIcon />
                {text.expired}
              </p>
            ) : null}
            {!state.expired && expiry !== undefined && text.expiresIn && state.decided === null ? (
              <Countdown expiresAt={expiry} expiresIn={text.expiresIn} />
            ) : null}
            {state.error === null ? null : (
              <Alert data-slot="device-approval-error" tone="destructive" live>
                <AlertDescription className="text-foreground">
                  {rejectionContent(state.error, text.error)}
                </AlertDescription>
              </Alert>
            )}
            {hasContent(decision) ? (
              <Alert
                data-slot="device-approval-decided"
                tone={state.decided === "approve" ? "success" : "neutral"}
                live
              >
                <AlertDescription>{decision}</AlertDescription>
              </Alert>
            ) : null}
            {showBlockedReason ? (
              <p
                id={blockedReasonId}
                data-slot="device-approval-blocked"
                className="flex items-center justify-end gap-inline text-end text-body-sm text-muted-foreground narrow:justify-start narrow:text-start [&_svg]:size-4 [&_svg]:shrink-0"
              >
                <CircleSlashIcon />
                {approveBlockedReason}
              </p>
            ) : null}
            <div
              data-slot="device-approval-actions"
              className="flex flex-wrap items-center justify-end gap-items narrow:flex-col-reverse narrow:items-stretch"
            >
              {props.actions === undefined ? (
                <>
                  <Button
                    variant="outline"
                    className="narrow:w-full"
                    loading={state.pending === "deny"}
                    disabled={state.expired || state.decided !== null || state.pending === "approve"}
                    onClick={(event) => {
                      const result = api.deny(event.nativeEvent)
                      if (result instanceof Promise) result.then(undefined, ignoreRefusal)
                    }}
                  >
                    {text.deny}
                  </Button>
                  <ApproveButton
                    approve={(event) => api.approve(event)}
                    blocked={actionState.approveBlocked || state.decided !== null || state.pending === "deny"}
                    pending={state.pending === "approve"}
                    describedBy={showBlockedReason ? blockedReasonId : undefined}
                    agentConfirm={text.approveAgentConfirm}
                  >
                    {text.approve}
                  </ApproveButton>
                </>
              ) : typeof props.actions === "function" ? (
                props.actions(actionState)
              ) : (
                props.actions
              )}
            </div>
          </>
        )
      },
    },
  )
}

